package com.jadhavr.erp.fee.controller; import com.jadhavr.erp.common.api.ApiResponse; import com.jadhavr.erp.common.dto.PageResponse; import com.jadhavr.erp.fee.dto.*; import com.jadhavr.erp.fee.enums.*; import com.jadhavr.erp.fee.service.FeeService; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/fee-section") public class FeeSectionController {private final FeeService s;public FeeSectionController(FeeService s){this.s=s;}@GetMapping("/dashboard")public ApiResponse<FeeDashboardResponse> dashboard(){return ApiResponse.success("Fee dashboard retrieved",s.dashboard());}@GetMapping("/fee-accounts")public ApiResponse<PageResponse<StudentFeeAccountResponse>> accounts(@RequestParam(required=false)String keyword,@RequestParam(required=false)Long collegeId,@RequestParam(required=false)Long departmentId,@RequestParam(required=false)FeeAccountStatus status,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="10")int size){return ApiResponse.success("Fee accounts retrieved",s.searchAccounts(keyword,collegeId,departmentId,status,page,size));}@GetMapping("/fee-accounts/{id}")public ApiResponse<StudentFeeAccountResponse> account(@PathVariable Long id){return ApiResponse.success("Fee account retrieved",s.getAccount(id));}@GetMapping("/fee-accounts/{id}/transactions")public ApiResponse<List<FeeTransactionResponse>> transactions(@PathVariable Long id){return ApiResponse.success("Transactions retrieved",s.accountTransactions(id));}@GetMapping("/payments")public ApiResponse<PageResponse<PaymentResponse>> payments(@RequestParam(required=false)String keyword,@RequestParam(required=false)Long collegeId,@RequestParam(required=false)Long departmentId,@RequestParam(required=false)PaymentStatus status,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="10")int size){return ApiResponse.success("Payments retrieved",s.searchPayments(keyword,collegeId,departmentId,status,page,size));}@GetMapping("/payments/{id}")public ApiResponse<PaymentResponse> payment(@PathVariable Long id){return ApiResponse.success("Payment retrieved",s.getPayment(id));}@PatchMapping("/payments/{id}/verify")public ApiResponse<PaymentResponse> verify(@PathVariable Long id,@Valid @RequestBody VerifyPaymentRequest r){return ApiResponse.success("Payment verified",s.verify(id,r));}@PatchMapping("/payments/{id}/reject")public ApiResponse<PaymentResponse> reject(@PathVariable Long id,@Valid @RequestBody RejectPaymentRequest r){return ApiResponse.success("Payment rejected",s.reject(id,r));}@PatchMapping("/payments/{id}/request-resubmission")public ApiResponse<PaymentResponse> resubmit(@PathVariable Long id,@Valid @RequestBody RejectPaymentRequest r){return ApiResponse.success("New payment proof requested",s.requestResubmission(id,r));}@PatchMapping("/payments/{id}/reopen")public ApiResponse<PaymentResponse> reopen(@PathVariable Long id){return ApiResponse.success("Payment reopened for verification",s.reopen(id));}}
